# -*- coding: utf-8 -*-
# document id -> (what it responded to, how it was received / what it provoked, related document ids)
DOCX = {
 'old-roman': ('Baptismal candidates at Rome confessed this faith in three questions and answers, following the threefold name of Matthew 28:19.',
               'Expanded in Gaul over the following centuries into the Apostles’ Creed. Rufinus’ commentary (c. 404) made the Roman text widely known in the West.', ['apostles', 'nicaea325']),
 'apostles': ('Grew out of the Roman baptismal creed as Gallic and Spanish churches added clauses such as “descended into hell” and “communion of saints”.',
              'Became the standard baptismal creed of the West; Charlemagne’s reforms spread it. Lutheran, Reformed, Anglican and Methodist churches kept it, and catechisms such as Heidelberg are built on it. The Orthodox never adopted it liturgically: at Ferrara (1438) the Greek delegates said they did not know it.', ['old-roman', 'nicene', 'heidelberg', 'art39']),
 'nicaea325': ('Arius’ teaching that the Son was a creature, “there was when he was not”, divided Alexandria and spread through the East from about 318.',
               'Resisted for decades: many bishops disliked homoousios, and imperial councils of the 350s replaced it. Athanasius and later the Cappadocians defended it, and Constantinople (381) confirmed it in the enlarged creed now called Nicene.', ['nicene', 'chalcedon', 'cyril12']),
 'nicene': ('The settlement under Theodosius I after fifty years of conflict, and the new debate over the divinity of the Holy Spirit.',
            'Read at Chalcedon (451) as the creed of the 150 fathers and became the creed of the Eucharist in East and West. The Latin addition of the Filioque (Toledo, 589; Rome, 1014) became a lasting point of division. Several Anglican and Lutheran bodies now permit or recommend reciting it without the addition.', ['nicaea325', 'athanasian', 'apostles', 'chalcedon']),
 'chalcedon': ('The conflict between Cyril’s heirs and the Antiochene tradition, the condemnation of Eutyches in 448 and the “Robber Synod” of 449.',
               'Accepted by Rome and Constantinople but rejected by much of Egypt, Syria and Armenia, where the Oriental Orthodox churches took shape. The Henotikon (482) failed to heal the split. Modern agreed statements (1973, 1989–90) found that both sides confess the same faith in different words.', ['cyril12', 'const3', 'nicene']),
 'athanasian': ('Western teaching on the Trinity and Christ shaped by Augustine, probably written to instruct clergy in southern Gaul.',
                'Sung at the daily office in the medieval West and included in the Lutheran Book of Concord (1580) and the Anglican Book of Common Prayer. Its warning clauses (“which except a man believe…”) have been debated since the nineteenth century. It has no place in Eastern liturgy.', ['nicene', 'chalcedon', 'augsburg']),
 'cyril12': ('Nestorius’ refusal to call Mary Theotokos and his preaching that the Word and the man Jesus should be distinguished.',
             'Nestorius rejected them, and the Antiochenes, led by John of Antioch and Theodoret, attacked them as Apollinarian. The Formula of Reunion (433) passed over them. The Second Council of Constantinople (553) vindicated Cyril’s teaching against Theodoret’s critique.', ['chalcedon', 'nicene']),
 'const3': ('Imperial attempts (Monoenergism, then the Ekthesis of 638 and the Typos of 648) to reconcile the miaphysites by speaking of one will in Christ.',
            'Ended the Monothelite policy and vindicated Maximus the Confessor and Pope Martin I, both of whom had died after mistreatment. Its condemnation of Pope Honorius was cited in the nineteenth-century debate over papal infallibility.', ['chalcedon', 'nicaea2', 'pastor']),
 'nicaea2': ('The iconoclasm imposed by the emperors Leo III and Constantine V and confirmed by the Council of Hieria (754).',
             'Iconoclasm returned from 815 until the final restoration of 843, celebrated each year as the “Triumph of Orthodoxy”. In the West a poor Latin translation led the Frankish Libri Carolini and the Council of Frankfurt (794) to reject it; Rome accepted it. Most Protestant churches reject the veneration of images.', ['const3']),
 'milan': ('The Great Persecution (303–311), Galerius’ edict of toleration (311), and Constantine’s victory at the Milvian Bridge (312).',
           'Ended persecution and returned confiscated property, beginning the Church’s shift from tolerated minority to imperial favour that led to Theodosius’ laws making Nicene Christianity the religion of the empire (380).', ['nicaea325']),
 'unam': ('The conflict between Boniface VIII and Philip IV of France over taxing the clergy and royal authority over bishops.',
          'Philip’s men seized Boniface at Anagni (1303); he died weeks later. Clement V declared (Meruit, 1306) that the bull changed nothing in France’s position. Its final sentence is regarded as a solemn definition, but later Catholic teaching, especially Vatican II, has placed it in a wider context.', ['pastor', 'tridentine']),
 'trent6': ('Luther’s and the Reformers’ teaching on justification by faith alone, set out in the Augsburg Confession and its Apology.',
            'Attacked by Protestant theologians, notably Martin Chemnitz’s Examination of the Council of Trent (1565–73), and remained Catholic teaching. The Joint Declaration of 1999 stated that the mutual condemnations of the sixteenth century do not apply to the teaching each church now presents.', ['augsburg', 'dort', 'westminster', 'tridentine']),
 'tridentine': ('The need, after Trent, for a single test of Catholic belief for clergy, teachers and converts.',
                'Required for four centuries; replaced in 1967 by a shorter profession and in 1989 by the current Profession of Faith.', ['trent6', 'nicene', 'pastor']),
 'ineffabilis': ('Centuries of devotion and debate over Mary’s conception (Franciscans for, many Dominicans against), and Pius IX’s consultation of the bishops in 1849.',
                 'Received with celebration in Catholic countries; at Lourdes in 1858 Bernadette reported the words “I am the Immaculate Conception”. Orthodox and Protestant churches generally do not accept it as dogma, though many Orthodox honour Mary as all-holy.', ['pastor', 'tridentine']),
 'pastor': ('The loss of the Papal States, liberalism and Gallican and conciliarist views of church authority.',
            'A minority of bishops left Rome rather than vote against it. Döllinger was excommunicated (1871) and the Old Catholic churches formed; in Germany the Kulturkampf followed. Vatican II (Lumen gentium) set papal primacy beside the collegiality of bishops, and John Paul II’s Ut unum sint (1995) invited other churches to discuss how primacy is exercised.', ['unam', 'ineffabilis', 'const3']),
 'theses95': ('The indulgence preaching of Johann Tetzel for the rebuilding of St Peter’s and Archbishop Albrecht of Mainz’s debts.',
              'Printed and circulated across Germany within weeks. Debates followed at Heidelberg (1518) and Leipzig (1519), and Leo X excommunicated Luther in 1521. 31 October is kept as Reformation Day.', ['augsburg', 'trent6']),
 'augsburg': ('Charles V’s summons to the Diet of Augsburg to settle the religious divisions in the Empire.',
              'Catholic theologians answered with the Confutation (1530) and Melanchthon replied with the Apology. The Peace of Augsburg (1555) recognised Lutheran territories. It remains the basic confession of Lutheran churches.', ['theses95', 'trent6', 'art39', 'athanasian']),
 'heidelberg': ('Elector Frederick III’s turn to the Reformed faith in the Palatinate and the need to teach it.',
                'Adopted at Dort (1618–19) as one of the “Three Forms of Unity” with the Belgic Confession and the Canons of Dort; translated into dozens of languages. Some churches have since bracketed question 80, which calls the Mass “accursed idolatry”.', ['belgic', 'dort', 'apostles']),
 'belgic': ('Persecution of Protestants in the Spanish Netherlands; de Brès wrote it to show the authorities that Reformed believers were not rebels.',
            'De Brès was executed in 1567. Revised at Dort (1619), it became one of the Three Forms of Unity of the Dutch Reformed tradition.', ['heidelberg', 'dort']),
 'dort': ('The Remonstrance of 1610, in which followers of Jacobus Arminius challenged Reformed teaching on predestination and grace.',
          'Remonstrant ministers were deposed; the dispute was bound up with Dutch politics, and the statesman Oldenbarnevelt was executed in 1619. The acronym “TULIP” for its five points is a much later invention.', ['belgic', 'heidelberg', 'westminster', 'trent6']),
 'westminster': ('Parliament’s plan, during the Civil War, for a reformed Church of England in line with Scotland.',
                 'Never adopted in England for long, but adopted by the Church of Scotland (1647) and by Presbyterians worldwide. Congregationalists (Savoy Declaration, 1658) and Baptists (1689) adapted it; American Presbyterians revised it in 1788 and 1903.', ['wsc', 'dort', 'art39']),
 'wsc': ('The Westminster Assembly’s plan to teach its doctrine to children and new believers.',
         'Memorised for generations in Scotland, England and America; its first answer, that our chief end is “to glorify God, and to enjoy him for ever”, became proverbial.', ['westminster', 'heidelberg']),
 'art39': ('The Elizabethan settlement of religion after the reigns of Edward VI and Mary I.',
           'Subscription was required of clergy by law from 1571. Newman’s Tract 90 (1841) argued that they could be read in a Catholic sense, causing an uproar. Subscription was relaxed in 1865 and 1975. Wesley abridged them for American Methodists.', ['methodist', 'westminster', 'augsburg']),
 'methodist': ('American independence and Wesley’s decision to provide American Methodists with their own ministry and doctrinal standards.',
               'Adopted at the Christmas Conference in Baltimore (1784), with an added article on the American government, making twenty-five. United Methodist “restrictive rules” protect them from change.', ['art39']),
 'lambeth': ('Nineteenth-century hopes for reunion among Protestant churches and with the historic churches.',
             'Became the basis of Anglican ecumenical proposals, including the Church of South India (1947) and later Anglican–Lutheran agreements such as Porvoo (1992) and Called to Common Mission (1999).', ['nicene', 'apostles']),
}
